#!/usr/bin/env bash\n\n# nightly-uptime-emoji: displays system uptime with emojis\n\n# Retrieve uptime in "up X ..." format; fallback to 0 minutes if unavailable\nget_uptime() {\n  if command -v uptime >/dev/null 2>&1; then\n    uptime -p 2>/dev/null || echo "up 0 minutes"\n  else\n    echo "up 0 minutes"\n  fi\n}\n\n# Strip leading "up " and return the remainder\nparse_uptime() {\n  local raw="$1"\n  raw="${raw#up }"\n  echo "$raw"\n}\n\n# Convert a time‑unit string to its emoji representation\nto_emoji() {\n  local part="$1"\n  case "$part" in\n    *day*) echo -n "🌞 " ;;\n    *hour*) echo -n "⏰ " ;;\n    *minute*) echo -n "🕒 " ;;\n    *week*) echo -n "📅 " ;;\n    *month*) echo -n "🗓️ " ;;\n    *) echo -n "" ;;\n  esac\n}\n\n# Main function – builds the emoji‑enhanced uptime string\nmain() {\n  local raw=$(get_uptime)\n  local parsed=$(parse_uptime "$raw")\n  local output=""\n  IFS=',' read -ra parts <<< "$parsed"\n  for p in "${parts[@]}"; do\n    p=$(echo "$p" | xargs)  # trim whitespace\n    if [[ -n \"$p\" ]]; then\n      output+=$(to_emoji "$p")\n      output+="$p; "\n    fi\n  done\n  echo "Uptime: $output"\n}\n\n# Execute when run directly\nif [[ "${BASH_SOURCE[0]}" == "${0}" ]]; then\n  main\nfi\n
